"""Participating clubs receive approved summaries, not lead-club private operational records."""
from support import Client,sql
import uuid,json,pathlib,datetime
results=[];f=json.loads(pathlib.Path('test-results/phase6-fixture.json').read_text());club2=sql("SELECT \"Id\" FROM \"Orgs\" WHERE \"Code\"='GC-007'")
def check(name,ok):
 results.append({'test':name,'passed':bool(ok)});pathlib.Path('test-results/phase6-scope.json').write_text(json.dumps(results,indent=2));print(('PASS ' if ok else 'FAIL ')+name,flush=True);assert ok,name
def good(c,p,m='GET',d=None,status=200):
 code,b=c.req(p,m,d);assert code==status,(p,code,b);return b
c=Client();assert c.login('admin@example.test')[0]==200;root=next(w for w in c.req('/workspaces')[1] if w['role']=='Association Super Admin' and w['association'].startswith('Global'));c.activate(root);review=Client();review.login('secretary@example.test');review.activate(next(w for w in review.req('/workspaces')[1] if w['role']=='Association Super Admin' and w['orgId']==root['orgId']));partner=Client();partner.login('manager@example.test');role=next(r for r in good(c,'/roles') if r['name']=='Club Manager');existing=next((w for w in good(partner,'/workspaces') if w['role']=='Club Manager' and w['orgId']==club2),None);temporary=existing is None
if temporary:good(c,'/assignments','POST',{'email':'manager@example.test','roleId':role['id'],'orgId':club2},204)
pw=next(w for w in good(partner,'/workspaces') if w['role']=='Club Manager' and w['orgId']==club2);partner.activate(pw)
try:
 now=datetime.datetime.now(datetime.timezone.utc);p=good(c,'/projects','POST',{'orgId':f['clubId'],'name':'Partner scope '+uuid.uuid4().hex[:8],'managerId':f['personId'],'startsAt':now.isoformat(),'endsAt':(now+datetime.timedelta(days=3)).isoformat(),'participatingClubs':[club2]});check('partner cannot read unapproved draft',partner.req('/projects/'+p['id'])[0]==404);request=good(c,'/projects/'+p['id']+'/submit','POST',{});check('partner cannot read submitted unapproved summary',partner.req('/projects/'+p['id'])[0]==404);request=good(c,'/governance/requests/'+request['id'])['request'];good(review,'/governance/requests/'+request['id']+'/decisions','POST',{'decision':'Approve','version':request['version'],'comment':'Independent joint project review'});d=good(partner,'/projects/'+p['id']);check('approved partner receives summary without private master',d['project'] is None and d['summary']['status']=='Approved');check('partner sees only its own contribution relationship',len(d['organizations'])==1 and d['organizations'][0]['orgId']==club2);check('partner cannot operate lead project',partner.req('/projects/'+p['id']+'/status','POST',{'status':'Planning','version':1})[0]==404);check('unapproved project absent from cross-scope listing',all(x['status'] not in ['Draft','Submitted','Rejected','Changes Requested'] for x in good(partner,'/projects')))
finally:
 if temporary:good(c,'/assignments/'+pw['id'],'DELETE',{},204)

# A recipient/project manager holding an eligible reviewer role still cannot approve their own outcome.
member=Client();member.login('member@example.test');superrole=next(r for r in good(c,'/roles') if r['name']=='Association Super Admin');existing=next((w for w in good(member,'/workspaces') if w['role']=='Association Super Admin' and w['orgId']==root['orgId']),None);temporary=existing is None
if temporary:good(c,'/assignments','POST',{'email':'member@example.test','roleId':superrole['id'],'orgId':root['orgId']},204)
memberw=next(w for w in good(member,'/workspaces') if w['role']=='Association Super Admin' and w['orgId']==root['orgId']);member.activate(memberw)
try:
 template=good(c,'/certificate-templates','POST',{'orgId':f['clubId'],'name':'Conflict QA '+uuid.uuid4().hex[:8],'type':'Appreciation','layout':{'orientation':'Landscape','background':'#fffdf5','border':'#b39755','elements':[{'text':'{{member_name}}','x':50,'y':50,'size':30}]}});membership=sql(f"SELECT \"Id\" FROM \"Memberships\" WHERE \"PersonId\"='{f['personId']}' AND \"ClubId\"='{f['clubId']}' AND \"Status\"='Active' LIMIT 1");cert=good(c,'/certificates','POST',{'orgId':f['clubId'],'templateId':template['id'],'people':[f['personId']],'sourceType':'Membership','sourceId':membership})[0];request=good(c,'/governance/requests/'+cert['requestId'])['request'];check('certificate recipient cannot approve own outcome',member.req('/governance/requests/'+request['id']+'/decisions','POST',{'decision':'Approve','version':request['version'],'comment':'Own award'})[0]==403)
 project=good(c,'/projects','POST',{'orgId':f['clubId'],'name':'Manager conflict QA '+uuid.uuid4().hex[:8],'managerId':f['personId'],'startsAt':now.isoformat(),'endsAt':(now+datetime.timedelta(days=1)).isoformat()});request=good(c,'/projects/'+project['id']+'/submit','POST',{});check('project manager cannot approve own project',member.req('/governance/requests/'+request['id']+'/decisions','POST',{'decision':'Approve','version':request['version'],'comment':'Own project'})[0]==403)
finally:
 if temporary:good(c,'/assignments/'+memberw['id'],'DELETE',{},204)

# Explicit invitations/shares are narrow record grants, not broader organizational write permissions.
member.activate(next(w for w in good(member,'/workspaces') if w['role']=='Club Member' and w['orgId']==f['clubId']));meeting=good(c,'/meetings','POST',{'orgId':root['orgId'],'title':'Invited ancestor meeting '+uuid.uuid4().hex[:8],'startsAt':now.isoformat(),'endsAt':(now+datetime.timedelta(hours=1)).isoformat(),'visibility':'Confidential','requiredPeople':[f['personId']]});check('explicit invite permits ancestor meeting read',member.req('/meetings/'+meeting['id'])[0]==200);check('invite does not grant ancestor meeting write',member.req('/meetings/'+meeting['id']+'/status','POST',{'status':'Scheduled','version':meeting['version']})[0]==403);manager=Client();manager.login('manager@example.test');manager.activate(next(w for w in good(manager,'/workspaces') if w['role']=='Club Manager' and w['orgId']==f['clubId']));check('uninvited peer still cannot read ancestor meeting',manager.req('/meetings/'+meeting['id'])[0]==404)
memberuser=sql(f"SELECT \"UserId\" FROM \"Persons\" WHERE \"Id\"='{f['personId']}'");code,doc=c.upload('/documents','shared.pdf',b'%PDF-1.4\nFictional explicitly shared record\n%%EOF',{'orgId':root['orgId'],'title':'Narrow document share','visibility':'Private','sharedUsers':json.dumps([memberuser])},'application/pdf');assert code==200,doc;check('explicit document share permits cross-org read only',member.request('/documents/'+doc['id']+'/download')[0]==200 and manager.request('/documents/'+doc['id']+'/download')[0]==404)

check('ordinary member identity picker contains own person only',all(p['id']==f['personId'] for p in good(member,'/operations/options')['people']));check('ordinary member cannot enumerate issuance source records',member.req('/operations/certificate-sources?type=Project')[0]==403);sources=good(c,'/operations/certificate-sources?type=Project');check('issuer source picker returns scoped human-readable labels',bool(sources) and all(set(x)=={'id','label'} and bool(x['label']) for x in sources))

# Parent-issued membership certificates preserve the recipient's actual club context.
parentcert=good(c,'/certificates','POST',{'orgId':root['orgId'],'templateId':template['id'],'people':[f['personId']],'sourceType':'Membership','sourceId':membership})[0];context=good(c,'/governance/requests/'+parentcert['requestId'])['operation']['content'];check('parent issuance freezes actual membership club name',context['club_name']==sql(f"SELECT \"Name\" FROM \"Orgs\" WHERE \"Id\"='{f['clubId']}'"))

# Linking attendance must preserve the existing event service's source authority.
event=sql(f"SELECT e.\"Id\" FROM \"Events\" e WHERE e.\"OrgId\"='{f['clubId']}' AND e.\"Visibility\"='Public' AND e.\"Publication\"='Published' AND e.\"Lifecycle\"!='Cancelled' AND NOT EXISTS(SELECT 1 FROM \"EventStaff\" st WHERE st.\"EventId\"=e.\"Id\" AND st.\"PersonId\" IN('{f['personId']}','{f['managerPersonId']}') AND st.\"Active\" AND st.\"Capability\" IN('Manage','Checkin')) LIMIT 1");assert event
code,limitedrole=c.req('/roles','POST',{'name':'Operations-only bridge QA '+uuid.uuid4().hex[:8],'permissions':['organization.view','operations.view','operations.manage']});assert code==200,limitedrole;good(c,'/assignments','POST',{'email':'manager@example.test','roleId':limitedrole['id'],'orgId':f['clubId']},204);limitedw=next(w for w in good(manager,'/workspaces') if w['role']==limitedrole['name']);manager.activate(limitedw)
try:
 body={'orgId':f['clubId'],'title':'Source authority QA','startsAt':now.isoformat(),'endsAt':(now+datetime.timedelta(hours=1)).isoformat(),'eventId':event};check('operations permission cannot bypass event source authority',manager.req('/meetings','POST',body)[0]==403)
finally:good(c,'/assignments/'+limitedw['id'],'DELETE',{},204)
linked=good(c,'/meetings','POST',body);attendance=good(member,'/meetings/'+linked['id']+'/attendance');check('public event quorum does not disclose staff-only source roster',attendance['source']=='Event' and attendance['rows']==[])

# Original governance documents never silently lose their earlier access/retention policy.
code,legacy=c.upload('/governance/documents','original.pdf',b'%PDF-1.4\nFictional legacy governance source\n%%EOF',{'orgId':f['clubId'],'title':'Original governance interoperability','kind':'Policy','shareWithSuccessors':'false'},'application/pdf');assert code==200,legacy
check('legacy source cannot silently convert through version append',c.upload('/documents/'+legacy['id']+'/versions','v2.pdf',b'%PDF-1.4\nFictional revision\n%%EOF',{'version':1},'application/pdf')[0]==409);check('legacy source cannot acquire misleading new sharing flags',c.req('/documents/'+legacy['id'],'PUT',{'title':'Original governance interoperability','folder':'Board','tags':'','visibility':'Private','sharedUsers':[]})[0]==409);sql(f"UPDATE \"GovernanceDocuments\" SET \"RetainUntil\"=now()-interval '1 minute' WHERE \"Id\"='{legacy['id']}'");check('vault delivery respects legacy retention before cleanup',c.request('/documents/'+legacy['id']+'/download')[0]==410)
print(str(len(results))+' Phase 6 scope checks passed')
